// Removes `workspace:*` dependencies from the package.json generated by the build.
// Webpack bundles the workspace libraries into main.js, and outside the monorepo
// pnpm cannot resolve `workspace:*`, so the deploy output could not be installed.
import { readFileSync, writeFileSync } from 'node:fs';

const packageJsonPath = 'dist/apps/backend/package.json';

const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf8'));

for (const [name, spec] of Object.entries(packageJson.dependencies)) {
  if (spec.startsWith('workspace:')) {
    delete packageJson.dependencies[name];
  }
}

writeFileSync(packageJsonPath, `${JSON.stringify(packageJson, null, 2)}\n`);
